// Generated by GitHub Copilot - Oct-23-2026
const STEPS = ['Selector', 'Mixing', 'Recipes', 'Recipe Card'];

/** Four-step progress indicator for the JAIME flow. `current` is 0-based. */
export default function Stepper({ current }: { current: number }) {
  return (
    <ol className="stepper" aria-label="Progress">
      {STEPS.map((label, i) => {
        const state = i < current ? 'done' : i === current ? 'active' : 'todo';
        return (
          <li key={label} className={`stepper__item stepper__item--${state}`} aria-current={state === 'active' ? 'step' : undefined}>
            <span className="stepper__dot">{state === 'done' ? '✓' : i + 1}</span>
            <span className="stepper__label">{label}</span>
            {state === 'done' && <span className="sr-only">(completed)</span>}
          </li>
        );
      })}
    </ol>
  );
}
